WITH "r0" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND ( "s"."id" < $1 ) ) SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT count( "t0" .*) AS "count" , row_to_json((SELECT "%" FROM (SELECT sum( "t0"."id" ) AS "id" ) AS "%")) AS "sum" , row_to_json((SELECT "%" FROM (SELECT avg( "t0"."id" ) AS "id" ) AS "%")) AS "avg" , row_to_json((SELECT "%" FROM (SELECT min( "t0"."id" ) AS "id" ) AS "%")) AS "min" , row_to_json((SELECT "%" FROM (SELECT max( "t0"."id" ) AS "id" ) AS "%")) AS "max" ) AS "%")) AS "aggregate" , coalesce(json_agg( "c1"."j" ), '[]') AS "nodes" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) AS "j" FROM (SELECT true) AS "_" ) AS "c1" ON true
